BEGIN;
CREATE TABLE fuel.fuel_types(code text PRIMARY KEY,label text NOT NULL,unit_code text NOT NULL REFERENCES core.units(code));
INSERT INTO fuel.fuel_types VALUES('diesel','Diesel','l'),('petrol','Benzin','l'),('lpg','LPG','l'),('cng','CNG','kg');
CREATE TABLE fuel.vehicles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),registration text NOT NULL DEFAULT '',fuel_type text NOT NULL REFERENCES fuel.fuel_types(code),notes text NOT NULL DEFAULT '',archived_at timestamptz,created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id));
CREATE TABLE fuel.odometer_series(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),vehicle_id uuid NOT NULL,started_on date NOT NULL,ended_on date,initial_reading numeric(18,6) NOT NULL CHECK(initial_reading>=0),reason text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),UNIQUE(household_id,vehicle_id,id),FOREIGN KEY(household_id,vehicle_id) REFERENCES fuel.vehicles(household_id,id),CHECK(ended_on IS NULL OR ended_on>=started_on));
CREATE TABLE fuel.fillups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),vehicle_id uuid NOT NULL,odometer_series_id uuid NOT NULL,occurred_on date NOT NULL,fuel_type text NOT NULL REFERENCES fuel.fuel_types(code),odometer numeric(18,6) NOT NULL CHECK(odometer>=0),quantity numeric(18,6) NOT NULL CHECK(quantity>0),total_minor bigint NOT NULL CHECK(total_minor>0 AND total_minor<=1000000000000),unit_price numeric(18,6) CHECK(unit_price>0),station text NOT NULL DEFAULT '',full_tank boolean NOT NULL DEFAULT true,previous_fill_missing boolean NOT NULL DEFAULT false,notes text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),FOREIGN KEY(household_id,vehicle_id,odometer_series_id) REFERENCES fuel.odometer_series(household_id,vehicle_id,id));
CREATE INDEX fillups_vehicle_date ON fuel.fillups(household_id,vehicle_id,occurred_on,odometer,id);
GRANT USAGE ON SCHEMA fuel TO household_app; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA fuel TO household_app;
COMMIT;
